theorem.content:
\label{thm:connectedSum}
	Let $M^n$ be a closed aspherical manifold and $N$ a spin manifold. Assume that the rational strong Novikov conjecture holds for $\pi_1(M)$.
	Then the connected sum $M\# N$ does not carry any complete metric with positive scalar curvature. Furthermore, any complete metric with non-negative scalar curvature on $M\# N$ is Ricci-flat.

ref_dict.thm:main:
\begin{theorem}\label{thm:main}
	Let $M^n$ be a closed aspherical manifold and $\Omega\subset M$ a smooth region. Assume that
	$$\pi_1(\Omega)\to \pi_1(M)\textup{ is the trivial map}.$$
	Let $N^n$ be a spin manifold with boundary, and $i\colon \partial N\to \partial \Omega$ a diffeomorphism preserving the spin structure\footnote{Although $M$ itself need not be spin, the triviality of $\pi_1(\Omega)\to\pi_1(M)$ implies that $\Omega$ and $\partial\Omega$ inherit a canonical spin structure from the spin universal cover $\widetilde M$.}. Set $Z\coloneqq (M\backslash\Omega)\cup_{\partial\Omega} N$. If the rational strong Novikov conjecture holds for $\pi_1(M)$, then $Z$ does not carry any complete metric with positive scalar curvature. Furthermore, any complete metric with non-negative scalar curvature on $Z$ is Ricci-flat.
\end{theorem}

ref_dict.example:
\begin{example}\label{example}
	Let $M^n$ be a closed aspherical spin manifold with $n\ge 5$, e.g., the $n$-torus. Suppose that $\pi_1(M)$ is represented by finitely many disjoint embedded circles $S^1$ in $M$, whose tubular neighborhoods are diffeomorphic to $S^1 \times B^{n-1}$. Remove these tubular neighborhoods and attach $B^2 \times S^{n-2}$ to obtain a closed manifold $M_1$. Then $M_1$ is simply connected.  

	Finally, set $Z \coloneqq M_1 \# M_1$, which is a spin surgery of $M$. Note that $Z$ is simply connected, and the Dirac operator on $Z$ has vanishing $KO$-index as $Z$ is a double. Hence, $Z$ admits a metric with positive scalar curvature \cite{Stolz}.
\end{example}

