\begin{thm}\label{thm:centrali.}
  Let $(A,N,\theta)_{\hH}$ be an $\hH$-triple. There exists an $\hH$-triple $(K,Z,\lambda)_{\hH}$ satisfying the following conditions.
  \begin{enumerate}
    \item There exists a group isomorphism $\epsilon:A/N\ra K/Z$ and we identify $\bar{A}=A/N$ with $K/Z.$ The subgroup $Z$ is $p'$-central in $K_{\lambda}$ and $\lambda$ is a faithful linear character of $Z.$ For any $J\in\mS(A,N),$ define $J^{\bullet}\leq K$ via $J^{\bullet}/Z=\epsilon(J/N).$
    \item $(\hH\times \bar A)_{\theta}=(\hH\times \bar A)_{\lambda}.$     \item For each $J\in\mS(A_{\theta},N),$ there exists a bijection $$\nu_J:\IBr(J\which \theta)\ra \IBr(J^{\bullet}\which\lambda)$$ 
        with the following properties:
\begin{enumerate}
  \item   $\nu_J(\chi)^a=\nu_{J^a}(\chi^a)$ for all $\chi\in\IBr(J\which\theta)$  and $a\in(\hH\times \bar A)_{\theta}$;
  \item   For any vertex $V$ of $\chi\in\IBr(J\which\theta),$ there exists a vertex $V_1$ of $\nu_{J}(\chi)$ satisfying $\bar V=V_1Z/Z$.
\end{enumerate}
We denote $\nu_J(\chi)$ by $\chi^{\bullet}.$

    \item     Let $N\subseteq Q\subseteq J\subseteq G$ be subgroups of $A$ with $Q/N$ a $p$-group and $J\subseteq A_{\theta}.$ 
        Let $\chi\in\IBr(J\which\theta)$ and $\varphi\in\IBr(\N_J(Q)\which \theta).$  
        Let $\ast\in\{\emptyset,c,b\}.$ 
        We write $H=\N_G(Q)$ and $M=\N_J(Q).$
        If $(G^{\bullet},J^{\bullet},\chi^{\bullet})_{\hH}$ and $(H^{\bullet},M^{\bullet},\varphi^{\bullet})_{\hH}$ are $\hH$-triples and $$(G^{\bullet},J^{\bullet},\chi^{\bullet})_{\hH}
        \geqslant_{\ast}
         (H^{\bullet},M^{\bullet},\varphi^{\bullet})_{\hH},$$
          then 
          $$(G,J,\chi)_{\hH}
        \geqslant_{\ast}
         (H,M,\varphi)_{\hH}.$$
  \end{enumerate}
  \end{thm}

